<#
.SYNOPSIS
    Diagnose and repair Microsoft Store apps without the Store.

.DESCRIPTION
    Self-contained remediation for missing or broken Store apps (Calculator,
    Snipping Tool, or any free Store app by ProductId). Diagnoses presence,
    missing components, and Store/update-channel reachability; repairs via
    staged re-register (elevated, no download) or a runtime fetch from
    Microsoft's update channel with hash + signature verification; installs
    with a dependency-mismatch retry ladder. As Local System it provisions
    machine-wide and hands the per-user install to the signed-in console user.
    Logs in CMTrace format (ConfigMgr standard).

    GENERATED FILE - do not hand-edit; regenerate with
    New-MsStoreRepairScript.ps1. Embedded fetcher:
    Get-MsStorePackageLink.ps1 (SHA-256 D8815934B61B3CB1EEE168F217E10729C6AD081925017E83101D1F3C27BFB824). Generated: 2026-09-11 23:54.

.PARAMETER App
    App shortcut(s): 'calc', 'snip', comma-separated ('calc,snip') or repeated.

.PARAMETER ProductId
    Microsoft Store product ID for any free app. Requires -ExpectedFamilyName.

.PARAMETER ExpectedFamilyName
    Package family name pin (e.g. Microsoft.WindowsCalculator_8wekyb3d8bbwe).
    Required with -ProductId: the Store catalog fuzzy-matches typo'd IDs to
    unrelated apps.

.PARAMETER Arch
    Package architecture: x64 (default), x86, arm64, all.

.PARAMETER DetectOnly
    Check health and exit without changing anything. Exit 0 = present,
    1 = missing.

.PARAMETER WorkDir
    Working directory for downloads and logs. Default %TEMP%\MsStoreRepair.

.EXAMPLE
    .\Repair-MsStoreApp.ps1 -App calc
    Diagnose and repair Calculator.

.EXAMPLE
    .\Repair-MsStoreApp.ps1 -App calc,snip -DetectOnly
    Health check both apps, change nothing.

.EXAMPLE
    .\Repair-MsStoreApp.ps1 -ProductId 9WZDNCRFHVN5 -ExpectedFamilyName Microsoft.WindowsCalculator_8wekyb3d8bbwe
    Repair any free Store app by pinned ProductId.

.NOTES
    Version:   3.2.2
    Author:    aushar0
    Exit codes 0 repaired/present, 1 input/pin/missing (DetectOnly),
    2 fetch failure, 3 signature failure, 4 install failure.
    Output: [INFO]/[WARN]/[ERR] clipped-narrative lines, a SUMMARY line, and
    a CMTrace-format log in <WorkDir>\Microsoft_StoreAppRepair_*.log.
#>
[CmdletBinding()]
param(
    [string[]]$App,
    [string]$ProductId,
    [string]$ExpectedFamilyName,
    [ValidateSet('x64', 'x86', 'arm64', 'all')]
    [string]$Arch = 'x64',
    [switch]$DetectOnly,
    [string]$WorkDir = "$env:TEMP\MsStoreRepair"
)

$ErrorActionPreference = 'Stop'

$known = @{
    calc = @{ ProductId = '9WZDNCRFHVN5'; FamilyName = 'Microsoft.WindowsCalculator_8wekyb3d8bbwe'; Title = 'Calculator' }
    snip = @{ ProductId = '9MZ95KL8MR0L'; FamilyName = 'Microsoft.ScreenSketch_8wekyb3d8bbwe';        Title = 'Snipping Tool' }
}

function Write-Log {
    # CMTrace format (ConfigMgr standard): severity renders colored in
    # CMTrace/OneTrace; the line stays readable as plain text. type 1/2/3 =
    # info/warning/error.
    param([string]$Level, [string]$Message)
    $type = switch ($Level) { 'ERR' { 3 } 'WARN' { 2 } default { 1 } }
    $now = Get-Date
    $tz = $now.ToString('zzz').Replace(':', '')
    $line = '<![LOG[{0}]LOG]!><time="{1:HH:mm:ss.fff}{2}" date="{1:MM-dd-yyyy}" component="StoreAppRepair" context="" type="{3}" thread="{4}" file="Repair-MsStoreApp.ps1">' -f `
        $Message, $now, $tz, $type, $PID
    $line | Out-File -FilePath $script:LogFile -Append -Encoding utf8
    if ($Level -ne 'DBG') { Write-Host $Message }
}

New-Item -ItemType Directory -Force -Path $WorkDir | Out-Null
$stamp   = Get-Date -Format 'yyyyMMdd-HHmmss'
$LogFile = Join-Path $WorkDir ("Microsoft_StoreAppRepair_{0}_{1}.log" -f $(if ($DetectOnly) { 'Check' } else { 'Repair' }), $stamp)
Write-Log 'INFO' ("Repair run. User: {0}. Mode: {1}." -f $env:USERNAME, $(if ($DetectOnly) { 'check only' } else { 'repair' }))
Write-Log 'INFO' "log=$LogFile"

$identity    = [Security.Principal.WindowsIdentity]::GetCurrent()
$isAdmin     = (New-Object Security.Principal.WindowsPrincipal($identity)).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
$isSystem    = $identity.User.Value -eq 'S-1-5-18'
$consoleUser = $null
if ($isSystem) { $consoleUser = (Get-CimInstance Win32_Computersystem -ErrorAction SilentlyContinue).UserName }
Write-Log 'INFO' ("Running as {0}. Elevated: {1}. System: {2}. Console user: {3}." -f $identity.Name, $isAdmin, $isSystem, $consoleUser)

# Registration-aware lookup: staged-but-unregistered (post-uninstall state)
# must not read as present - naive -AllUsers check no-ops real repairs.
function Get-AppxView {
    param([string]$Name)
    $view = @{ Registered = $null; Staged = $null }
    if ($isAdmin) {
        foreach ($p in @(Get-AppxPackage -Name $Name -AllUsers -ErrorAction SilentlyContinue)) {
            if ("$($p.PackageUserInformation)" -match 'Installed') {
                if (-not $view.Registered) { $view.Registered = $p }
            } elseif (-not $view.Staged) { $view.Staged = $p }
        }
    } else {
        # Unelevated -AllUsers is access-denied; current-user registration is
        # the visible and fixable surface.
        $view.Registered = Get-AppxPackage -Name $Name -ErrorAction SilentlyContinue | Select-Object -First 1
    }
    return $view
}

# Manifest-declared dependencies vs resolved; unelevated-safe for own packages.
function Get-DepGaps {
    param($Package)
    $gaps = @()
    if (-not $Package) { return $gaps }
    try {
        $manifest = Get-AppxPackageManifest -Package $Package -ErrorAction Stop
        foreach ($d in $manifest.Package.Dependencies.PackageDependency) {
            $have = Get-AppxPackage -Name $d.Name -ErrorAction SilentlyContinue
            if (-not $have -or ([version]$have[0].Version -lt [version]$d.MinVersion)) {
                $gaps += [pscustomobject]@{ Name = $d.Name; MinVersion = $d.MinVersion; Have = $(if ($have) { $have[0].Version } else { 'none' }) }
            }
        }
    } catch { Write-Log 'WARN' ("manifest read failed {0}: {1}" -f $Package.Name, $_.Exception.Message) }
    return $gaps
}

# DNS-poison (hosts 0.0.0.0) and TCP:443 reachability in one probe.
function Test-Endpoint {
    param([string]$Hostname)
    try {
        $ips = [Net.Dns]::GetHostAddresses($Hostname)
        if (($ips | Where-Object { $_.AddressFamily -eq 'InterNetwork' }).IPAddressToString -contains '0.0.0.0') { return 'blocked' }
        $tcp = New-Object Net.Sockets.TcpClient
        $ok = $tcp.BeginConnect($Hostname, 443, $null, $null).AsyncWaitHandle.WaitOne(3000)
        $tcp.Close()
        if ($ok) { return 'ok' } else { return 'unreachable' }
    } catch { return 'unreachable' }
}

# Trap registered after all definitions: it applies to the whole script scope
# regardless of position, so an early definition would miss its helpers.
trap {
    Write-Log 'ERR' ("unterminated failure: {0}" -f $_.Exception.Message)
    Write-Log 'ERR' ($_ | Out-String)
    break
}

$targets = @()
if ($App) {
    $App = $App | ForEach-Object { $_ -split ',' } | Where-Object { $_ }
    foreach ($a in $App) {
        if (-not $known.ContainsKey($a)) { Write-Log 'ERR' ("unknown app '{0}' known={1}" -f $a, ($known.Keys -join ',')); exit 1 }
        $targets += $known[$a]
    }
}
if ($ProductId) {
    if (-not $ExpectedFamilyName) {
        Write-Log 'ERR' "-ProductId requires -ExpectedFamilyName (catalog fuzzy-matches typo IDs to unrelated apps)"
        exit 1
    }
    $targets += @{ ProductId = $ProductId; FamilyName = $ExpectedFamilyName; Title = $ProductId }
}
if (-not $targets) { Write-Log 'ERR' 'no target: use -App calc[,snip] or -ProductId + -ExpectedFamilyName'; exit 1 }

# ---- diagnostics ----
$storeState   = Test-Endpoint 'storeedgefd.dsx.mp.microsoft.com'
$channelState = Test-Endpoint 'displaycatalog.mp.microsoft.com'
if ($storeState -eq 'ok' -and $channelState -eq 'ok') { Write-Log 'INFO' 'Microsoft Store reachable; update channel reachable.' }
    else { Write-Log 'WARN' ("Microsoft Store {0}; update channel {1}. Repairs fetch direct from the update channel." -f $storeState, $channelState) }

$overall   = 0
$raStatus  = @{}
$raVersion = @{}
$raAction  = 'none'

foreach ($t in $targets) {
    $pkgName = ($t.FamilyName -split '_')[0]
    $title   = $t.Title
    $raStatus[$pkgName] = 'unknown'; $raVersion[$pkgName] = ''
    Write-Log 'INFO' ("--- target {0} ({1}) ---" -f $title, $pkgName)

    $view = Get-AppxView -Name $pkgName
    if ($view.Registered) {
        $gaps = Get-DepGaps -Package $view.Registered
        if ($gaps.Count -eq 0) { Write-Log 'INFO' ("{0} healthy: version {1} registered, all required components present." -f $title, $view.Registered.Version) }
        else {
            Write-Log 'WARN' ("{0} present but incomplete: version {1}, {2} missing component(s)." -f $title, $view.Registered.Version, $gaps.Count)
            foreach ($g in $gaps) { Write-Log 'WARN' ("  Missing component: {0} requires version {1}, found {2}." -f $g.Name, $g.MinVersion, $g.Have) }
        }
        $raStatus[$pkgName] = $(if ($gaps.Count) { 'dep_missing' } else { 'healthy' })
        $raVersion[$pkgName] = $view.Registered.Version
    } elseif ($view.Staged) {
        Write-Log 'INFO' ("{0} staged on disk but not registered for any user." -f $title)
        $raStatus[$pkgName] = 'staged'
    } else {
        Write-Log 'INFO' ("{0} missing for this user; no staged copy visible." -f $title)
        $raStatus[$pkgName] = 'missing'
    }

    # Recent activation failures (TWinUI) and deployment-service events for the app.
    try {
        $twin = @(Get-WinEvent -LogName 'Microsoft-Windows-TwinUI/Operational' -MaxEvents 30 -ErrorAction Stop |
            Where-Object { $_.Message -match $pkgName -and $_.Message -notmatch 'completed successfully' } | Select-Object -First 3)
        if ($twin.Count) { Write-Log 'INFO' ("{0} recent launch failures logged: {1}." -f $twin.Count, $title) }
        foreach ($e in $twin) { Write-Log 'DBG' ("  twinui id={0} at={1} {2}" -f $e.Id, $e.TimeCreated, ($e.Message -split "`n")[0].Trim()) }
    } catch { Write-Log 'DBG' "twinui log read failed: $($_.Exception.Message)" }
    try {
        $dep = @(Get-WinEvent -LogName 'Microsoft-Windows-AppxDeploymentServer/Operational' -MaxEvents 100 -ErrorAction Stop |
            Where-Object { $_.Message -match $pkgName } | Select-Object -First 3)
        foreach ($e in $dep) { Write-Log 'DBG' ("  deployment id={0} at={1} {2}" -f $e.Id, $e.TimeCreated, ($e.Message -split "`n")[0].Trim()) }
    } catch { }

    if ($DetectOnly) {
        if ($raStatus[$pkgName] -ne 'healthy') { $overall = 1 }
        continue
    }

    # ---- repair path 1: staged + elevated -> re-register, no download ----
    if (-not $view.Registered -and $view.Staged -and $isAdmin -and -not $isSystem) {
        Write-Log 'INFO' ("{0} staged copy found; re-registering without download." -f $title)
        try {
            Add-AppxPackage -Path (Join-Path $view.Staged.InstallLocation 'AppxManifest.xml') -Register -DisableDevelopmentMode -ErrorAction Stop
            $now = Get-AppxPackage -Name $pkgName -ErrorAction SilentlyContinue
            if ($now) {
                Write-Log 'INFO' ("{0} re-registered at version {1}. No download needed." -f $title, $now.Version)
                $raStatus[$pkgName] = 'repaired'; $raVersion[$pkgName] = $now.Version
                $raAction = 'staged_reregister'
            }
        } catch {
            Write-Log 'WARN' ("staged re-register failed: {0} - falling through to fetch+install" -f $_.Exception.Message)
        }
    }

    # ---- repair path 2: fetch + install ----
    if (-not (Get-AppxPackage -Name $pkgName -ErrorAction SilentlyContinue)) {
        $dir = Join-Path $WorkDir $t.ProductId
        New-Item -ItemType Directory -Force -Path $dir | Out-Null
        $fetcher = Join-Path $WorkDir 'Get-MsStorePackageLink.ps1'
        if (-not (Test-Path $fetcher)) { [IO.File]::WriteAllBytes($fetcher, [Convert]::FromBase64String('')) }

Write-Log 'INFO' ("{0} missing. Fetching from the Microsoft update channel ({1})." -f $title, $t.ProductId)
        & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $fetcher $t.ProductId -Arch $Arch -Download -OutDirectory $dir *> (Join-Path $WorkDir 'fetch_out.txt')
        if ($LASTEXITCODE -ne 0) {
            Write-Log 'ERR' ("RESULT FAIL {0} fetch exit={1} (see fetch_out.txt)" -f $pkgName, $LASTEXITCODE)
            $raStatus[$pkgName] = 'fetch_failed'; $overall = 2
            continue
        }

        $files = @(Get-ChildItem $dir -File | Where-Object Extension -match '^\.(appx|msix)(bundle)?$')
        $badSig = @($files | Where-Object {
            $s = Get-AuthenticodeSignature $_.FullName
            $s.Status -ne 'Valid' -or $s.SignerCertificate.Subject -notmatch 'Microsoft'
        })
        if ($badSig.Count) {
            Write-Log 'ERR' ("RESULT FAIL {0} signature gate: {1}" -f $pkgName, ($badSig.Name -join ','))
            $raStatus[$pkgName] = 'signature_failed'; $overall = 3
            continue
        }
        Write-Log 'INFO' ("Fetched {0} files. All hashes verified against Microsoft's published digests; all signatures valid (Microsoft)." -f $files.Count)

        $frameworkPattern = '^(Microsoft\.(VCLibs|NET\.Native|UI\.Xaml|Services\.Store|Advertising|WindowsStore|Windows\..*SDK|WindowsAppRuntime)|Microsoft\.Windows\.SDK\..*)'
        $main = @($files | Where-Object { $_.Name -notmatch $frameworkPattern -and ($_.Name -split '_')[0] -eq $pkgName }) |
            Sort-Object { if ($_.Name -match '_(\d+\.\d+\.\d+\.\d+)_') { [version]$Matches[1] } else { [version]'0.0.0.0' } } -Descending |
            Select-Object -First 1
        if (-not $main) {
            Write-Log 'ERR' ("RESULT FAIL {0} PFN pin mismatch: no main package in downloaded set" -f $pkgName)
            $raStatus[$pkgName] = 'pin_mismatch'; $overall = 1
            continue
        }
        $deps = @($files | Where-Object Name -ne $main.Name)

        if ($isSystem) {
            # SYSTEM: no per-user appx (no profile; no -AllUsers on this cmdlet
            # set). Provision machine-wide, then per-user install for the
            # console user via one-shot scheduled task (no password from SYSTEM).
            Write-Log 'WARN' "SYSTEM branch: provision path implemented per the documented DISM lane; not yet validated on a managed device."
            Write-Log 'INFO' ("SYSTEM context: provisioning {0} machine-wide." -f $title)
            try {
                # -PackagePath, not -Path: -Path is the Offline image-servicing
                # set and collides with -Online (verified against the live cmdlet)
                $prov = @{ Online = $true; PackagePath = $main.FullName; SkipLicense = $true }
                if ($deps.Count) { $prov.DependencyPackagePath = $deps.FullName }
                Add-AppxProvisionedPackage @prov | Out-Null
                Write-Log 'INFO' "Provisioning completed."
                $raStatus[$pkgName] = 'provisioned'; $raAction = 'provision'
            } catch {
                Write-Log 'ERR' ("RESULT FAIL {0} provision: {1}" -f $pkgName, $_.Exception.Message)
                $raStatus[$pkgName] = 'failed'; $overall = 4
                continue
            }
            if ($consoleUser) {
                Write-Log 'INFO' ("ACTION console_user_handoff user={0}" -f $consoleUser)
                $okFile = Join-Path $WorkDir 'handoff_ok.txt'
                $errFile = Join-Path $WorkDir 'handoff_err.txt'
                # stale signal files from prior runs would corrupt the outcome read
                Remove-Item $okFile, $errFile -Force -ErrorAction SilentlyContinue
                # staged files live under SYSTEM's %TEMP% which the user cannot
                # read - copy the set to a user-readable location first
                $publicDir = 'C:\Users\Public\MsStoreRepair'
                New-Item -ItemType Directory -Force -Path $publicDir | Out-Null
                Copy-Item $main.FullName $publicDir -Force
                foreach ($d in $deps) { Copy-Item $d.FullName $publicDir -Force }
                $pubMain = Join-Path $publicDir $main.Name
                $pubDeps = @($deps | ForEach-Object { Join-Path $publicDir $_.Name })
                $depList = ($pubDeps | ForEach-Object { "'{0}'" -f $_ }) -join ','
                $handoffLines = @(
                    "`$err = ''"
                    "try { Add-AppxPackage -Path '$pubMain' -DependencyPath @($depList) -ErrorAction Stop } catch { `$err = `$_.Exception.Message }"
                    "if (`$err -match '0x80073CF3') {"
                    "  `$err = ''"
                    "  try { Add-AppxPackage -Path '$pubMain' -ErrorAction Stop } catch { `$err = `$_.Exception.Message }"
                    "  if (`$err -match '0x80073CF3') {"
                    "    `$err = ''"
                    "    foreach (`$f in @($depList)) { try { Add-AppxPackage -Path `$f -ErrorAction Stop } catch {} }"
                    "    try { Add-AppxPackage -Path '$pubMain' -ErrorAction Stop } catch { `$err = `$_.Exception.Message }"
                    "  }"
                    "}"
                    "if (`$err) { Set-Content -Path '$errFile' -Value `$err } else { Set-Content -Path '$okFile' -Value 'ok' }"
                )
                $handoffPs1 = Join-Path $publicDir 'handoff.ps1'
                Set-Content -Path $handoffPs1 -Value $handoffLines -Encoding utf8
                # hidden launcher: the task runs wscript which starts powershell
                # window-less - the user sees nothing (silence requirement)
                $runVbs = Join-Path $publicDir 'run_hidden.vbs'
                # [char]34 = double quote; avoids tripled-quote escapes entirely
                $q = [char]34
                $vbsLine = 'CreateObject("Wscript.Shell").Run ' + $q + 'powershell.exe -NoProfile -ExecutionPolicy Bypass -File ' + $q + $q + $handoffPs1 + $q + $q + ', 0, True'
                Set-Content -Path $runVbs -Value $vbsLine -Encoding ascii
                $action  = New-ScheduledTaskAction -Execute 'wscript.exe' -Argument ($q + $runVbs + $q)
                $tn = "MsStoreRepair-$pkgName-$stamp"
                try {
                    $trigger = New-ScheduledTaskTrigger -Once -At (Get-Date).AddSeconds(5)
                    # this build's Register-ScheduledTask takes -Principal (LogonType
                    # lives on the principal object), not bare -User/-LogonType
                    $principal = New-ScheduledTaskPrincipal -UserId $consoleUser -LogonType Interactive -RunLevel Limited
                    Register-ScheduledTask -TaskName $tn -Principal $principal -Action $action -Trigger $trigger -ErrorAction Stop | Out-Null
                    Start-ScheduledTask -TaskName $tn
                    $waited = 0
                    while ((Get-ScheduledTask -TaskName $tn).State -ne 'Ready' -and $waited -lt 120) { Start-Sleep -Seconds 2; $waited += 2 }
                    Unregister-ScheduledTask -TaskName $tn -Confirm:$false -ErrorAction SilentlyContinue
                } catch {
                    Write-Log 'WARN' ("handoff task failed: {0}" -f $_.Exception.Message)
                }
                if (Test-Path $okFile) {
                    Remove-Item $okFile -Force -ErrorAction SilentlyContinue
                    $post = @(Get-AppxPackage -Name $pkgName -AllUsers -ErrorAction SilentlyContinue | Where-Object { "$($_.PackageUserInformation)" -match 'Installed' })
                    if ($post) {
                        Write-Log 'INFO' ("{0} version {1} installed for console user {2}; provisioned machine-wide." -f $title, $post[0].Version, $consoleUser)
                        $raStatus[$pkgName] = 'repaired'; $raVersion[$pkgName] = $post[0].Version
                        $raAction = 'provision+console_user'
                    }
                } else {
                    $he = if (Test-Path $errFile) { (Get-Content $errFile -Raw).Trim() } else { 'task timeout' }
                    Remove-Item $errFile -Force -ErrorAction SilentlyContinue
                    Write-Log 'WARN' ("console_user_handoff incomplete: {0} - provision covers next logon" -f $he)
                }
            } else {
                Write-Log 'INFO' ("{0} provisioned; no one signed in, so it registers at next logon." -f $title)
            }
        }
        else {
            # User session: install with the 0x80073CF3 ladder (FE3 dependency
            # sets are a union across bundle inner packages).
            Write-Log 'INFO' ("ACTION install target={0} files={1}" -f $pkgName, ($deps.Count + 1))
            $installed = $false
            try {
                try {
                    $splat = @{ Path = $main.FullName }
                    if ($deps.Count) { $splat.DependencyPath = $deps.FullName }
                    Add-AppxPackage @splat -ErrorAction Stop
                    $installed = $true
                } catch {
                    $msg = $_.Exception.Message
                    if ($msg -notmatch '0x80073CF3') { throw }
                    if ($msg -match 'provided but not used') {
                        Write-Log 'INFO' 'First install rejected: components already satisfied (0x80073CF3). Retrying without them.'
                        try { Add-AppxPackage -Path $main.FullName -ErrorAction Stop; $installed = $true }
                        catch {
                            if ($_.Exception.Message -notmatch '0x80073CF3') { throw }
                            foreach ($d in $deps) {
                                try { Add-AppxPackage -Path $d.FullName -ErrorAction Stop }
                                catch { Write-Log 'WARN' ("Component {0}: {1}" -f $d.Name, $_.Exception.Message) }
                            }
                            Add-AppxPackage -Path $main.FullName -ErrorAction Stop
                            $installed = $true
                        }
                    } else {
                        foreach ($d in $deps) {
                            try { Add-AppxPackage -Path $d.FullName -ErrorAction Stop }
                            catch { Write-Log 'WARN' ("Component {0}: {1}" -f $d.Name, $_.Exception.Message) }
                        }
                        Add-AppxPackage -Path $main.FullName -ErrorAction Stop
                        $installed = $true
                    }
                }
            } catch {
                Write-Log 'ERR' ("RESULT FAIL {0} install: {1}" -f $pkgName, $_.Exception.Message)
                $raStatus[$pkgName] = 'failed'; $overall = 4
                continue
            }
            if ($installed) {
                $now = Get-AppxPackage -Name $pkgName -ErrorAction SilentlyContinue
                Write-Log 'INFO' ("{0} {1} installed for {2}." -f $title, $now.Version, $identity.Name)
                $raStatus[$pkgName] = 'repaired'; $raVersion[$pkgName] = $now.Version
                $raAction = 'fetch_install'
            }
        }
    }
    else {
Write-Log 'INFO' ("{0} already present. No action needed." -f $title)
        $raAction = 'none (already present)'
    }
}

$story = foreach ($t in $targets) {
    $n = ($t.FamilyName -split '_')[0]
    "{0}: {1}{2}" -f $t.Title, $raStatus[$n], $(if ($raVersion[$n]) { ", version " + $raVersion[$n] } else { "" })
}
$actionWords = switch -Wildcard ($raAction) {
    'none*'                       { 'No action needed.' }
    'fetch_install'               { 'Installed from the Microsoft update channel.' }
    'staged_reregister'           { 'Re-registered from existing files.' }
    'provision'                   { 'Provisioned machine-wide.' }
    'provision+console_user'      { 'Provisioned machine-wide and installed for the signed-in user.' }
    default                       { "$raAction." }
}
Write-Log 'INFO' ("SUMMARY: {0} $actionWords" -f ($story -join ' | '))
Write-Log 'INFO' ("Done. Exit code {0}. Full log: {1}" -f $overall, $LogFile)
[environment]::Exit($overall)